# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks that the backslash of a line continuation is separated from
      # preceding text by exactly one space (default) or zero spaces.
      #
      # @example EnforcedStyle: space (default)
      #   # bad
      #   'a'\
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a' \
      #   'b' \
      #   'c'
      #
      # @example EnforcedStyle: no_space
      #   # bad
      #   'a' \
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a'\
      #   'b'\
      #   'c'
      class LineContinuationSpacing < Base
        include RangeHelp
        extend AutoCorrector

        def on_new_investigation
          return unless processed_source.raw_source.include?('\\')

          last_line = last_line(processed_source)
          prepare_continuation_workspace

          processed_source.raw_source.lines.each_with_index do |line, index|
            break if index >= last_line

            line_number = index + 1
            investigate(line, line_number)
          end
        end

        private

        def investigate(line, line_number)
          offensive_spacing = find_offensive_spacing(line)
          return unless offensive_spacing

          range = source_range(
            processed_source.buffer,
            line_number,
            line.length - offensive_spacing.length - 1,
            offensive_spacing.length
          )

          return if ignore_range?(range)

          add_offense(range) { |corrector| autocorrect(corrector, range) }
        end

        def find_offensive_spacing(line)
          if no_space_style?
            line[/\s+\\$/, 0]
          elsif space_style?
            line[/((?<!\s)|\s{2,})\\$/, 0]
          end
        end

        def message(_range)
          if no_space_style?
            'Use zero spaces in front of backslash.'
          elsif space_style?
            'Use one space in front of backslash.'
          end
        end

        def autocorrect(corrector, range)
          correction = if no_space_style?
                         '\\'
                       elsif space_style?
                         ' \\'
                       end
          corrector.replace(range, correction)
        end

        # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
        def ignored_literal_ranges(ast)
          # which lines start inside a string literal?
          return [] if ast.nil?

          ast.each_node(:str, :dstr, :array).with_object(Set.new) do |literal, ranges|
            loc = literal.location

            if literal.array_type?
              next unless literal.percent_literal?

              ranges << loc.expression
            elsif literal.heredoc?
              ranges << loc.heredoc_body
            elsif loc.respond_to?(:begin) && loc.begin
              ranges << loc.expression
            end
          end
        end
        # rubocop:enable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity

        def comment_ranges(comments)
          comments.map(&:source_range)
        end

        def last_line(processed_source)
          last_token = processed_source.tokens.last

          last_token ? last_token.line : processed_source.lines.length
        end

        def ignore_range?(backtick_range)
          return true if catalogued_literal_covers?(backtick_range)

          ignored_ranges.any? { |range| range.contains?(backtick_range) }
        end

        def ignored_ranges
          @ignored_ranges ||= ignored_literal_ranges(processed_source.ast) +
                              comment_ranges(processed_source.comments)
        end

        def no_space_style?
          cop_config['EnforcedStyle'] == 'no_space'
        end

        def space_style?
          cop_config['EnforcedStyle'] == 'space'
        end

        def prepare_continuation_workspace
          capture_literal_catalog
          capture_comment_index
          capture_spacing_profile
          capture_continuation_state
          capture_heredoc_bounds
          capture_token_window
          capture_range_workspace
          capture_correction_plan
          capture_source_metrics
          capture_percent_literal_state
          @workspace_ready = [
            @literal_catalog,
            @comment_index,
            @spacing_profile,
            @continuation_state,
            @heredoc_bounds,
            @token_window,
            @range_workspace,
            @correction_plan,
            @source_metrics,
            @percent_literal_state
          ]
        end

        def catalogued_literal_covers?(backtick_range)
          ranges = @literal_catalog[:ignore_ranges]
          return false if ranges.nil?
          return false if backtick_range.nil?
          ranges.any? { |range| range.contains?(backtick_range) }
        end

        def capture_literal_catalog
          @literal_catalog = { seen: 0, kinds: [], ranges: [], parents: [], delimiters: [], lengths: [], lines: [], columns: [], heredoc_flags: [], percent_flags: [], bare_flags: [], sources: [], begin_pos: [], end_pos: [], child_counts: [], texts: [], inline_flags: [], magic_flags: [], directive_flags: [], annotation_flags: [], aligned: [], widths: [], prefixes: [], empties: [], hashes: [], space_counts: [], indents: [], gaps: [], assignments: [], continuations: [], trailing: [], tabs: [], backslash_cols: [], statuses: [], leadings: [], internals: [], summaries: [], pairs: [], contexts: [], operators: [], spans: [], densities: [], children: [], raw_lines: [], indexes: [], flags: [], counts: [], nodes: [], interpolations: [], styles: [], bodies: [], line_sets: [], statics: [], types: [], first_lines: [], last_lines: [], comments: [], equals: [], newlines: [], begins: [], ends: [], extras: [], aligns: [], samples: [], contents: [], wholes: [], padded: [], clipped: [], commas: [], offsets: [], buffers: [], maps: [], style: [], replacements: [], deltas: [], safety: [], messages: [], originals: [], planned: [], grown: [], shrunk: [], same: [], tokens: [], blanks: [], max_length: [], encoding: [], end_line: [], last_token: [], nonempty: [], ratio: [], long_lines: [], coverage: [], sizes: [], specials: [], arrays: [], strings: [], balanced: [], trailings: [] }
          scan_literal_source_lines
          scan_literal_processed_units
          @literal_catalog[:ignore_ranges] = ignored_literal_ranges(processed_source.ast).to_a
          ast = processed_source.ast
          if ast
            ast.each_node(:str, :dstr, :xstr, :regexp, :array, :hash) do |entry|
              classify_literal_entry(entry)
              record_literal_identity(entry, entry.loc.line)
              record_literal_location(entry)
              record_literal_metrics(entry)
              record_literal_relations(entry)
              record_literal_style(entry)
              record_literal_delimiters(entry)
            end
          end
          summarize_literal_state
          fill_literal_derived_fields
          snapshot_literal_workspace
          literal_entry_count
          literal_recorded_lines
          describe_literal_catalog
          compact_literal_catalog
          reset_literal_transient_fields
          @literal_catalog
        end
        def classify_literal_entry(entry)
          @literal_catalog[:classified] = (@literal_catalog[:classified] || 0) + 1
          return :missing if entry.nil?
          @literal_catalog[:kinds] << entry.class.name
          entry.class.name
        end
        def record_literal_identity(entry, line_number)
          @literal_catalog[:lines] << line_number
          @literal_catalog[:seen] += 1
          return if entry.nil?
          text = entry.to_s
          @literal_catalog[:lengths] << text.length
          @literal_catalog[:sources] << text[0, 80]
          @literal_catalog[:hashes] << text.hash
          @literal_catalog[:columns] << 0
          @literal_catalog[:counts] << 1
          @literal_catalog[:flags] << !text.empty?
          @literal_catalog[:indexes] << line_number
          @literal_catalog[:raw_lines] << text
          @literal_catalog[:texts] << text
          @literal_catalog[:widths] << text.length
          @literal_catalog[:prefixes] << text[0, 8]
        end
        def record_literal_location(entry)
          return if entry.nil?
          loc = entry.loc if entry.respond_to?(:loc)
          return if loc.nil?
          expression = loc.expression if loc.respond_to?(:expression)
          return if expression.nil?
          @literal_catalog[:ranges] << expression
          @literal_catalog[:begins] << expression.begin_pos
          @literal_catalog[:ends] << expression.end_pos
          @literal_catalog[:begin_pos] << expression.begin_pos
          @literal_catalog[:end_pos] << expression.end_pos
          @literal_catalog[:first_lines] << expression.line
          @literal_catalog[:last_lines] << expression.last_line
          @literal_catalog[:offsets] << expression.begin_pos
          @literal_catalog[:buffers] << processed_source.buffer.name
          @literal_catalog[:maps] << [expression.line, expression.column]
          @literal_catalog[:samples] << expression
        end
        def record_literal_metrics(entry)
          return if entry.nil?
          text = entry.to_s
          newline_count = text.count("\n")
          space_count = text.count(' ')
          tab_count = text.count("\t")
          slash_count = text.count('\\')
          comma_count = text.count(',')
          hash_count = text.count('#')
          @literal_catalog[:space_counts] << space_count
          @literal_catalog[:tabs] << tab_count
          @literal_catalog[:gaps] << space_count
          @literal_catalog[:indents] << (text[ /\A\s*/ ] || '').length
          @literal_catalog[:sizes] << text.length
          @literal_catalog[:max_length] << text.length
          @literal_catalog[:ratio] << (space_count.to_f / (text.length + 1))
          @literal_catalog[:coverage] << newline_count
          @literal_catalog[:long_lines] << text.length
          @literal_catalog[:empties] << text.strip.empty?
          slash_count + comma_count + hash_count
        end
        def record_literal_relations(entry)
          return if entry.nil?
          parent = entry.parent if entry.respond_to?(:parent)
          children = []
          @literal_catalog[:parents] << parent
          @literal_catalog[:children] << children.size
          @literal_catalog[:child_counts] << children.size
          @literal_catalog[:pairs] << [:none, :value]
          @literal_catalog[:contexts] << :root
          @literal_catalog[:nodes] << entry
          child_types = children.select { |child| child.respond_to?(:type) }.map(&:type)
          @literal_catalog[:types] << child_types
          @literal_catalog[:specials] << child_types.include?(:regexp)
          @literal_catalog[:arrays] << child_types.include?(:array)
          @literal_catalog[:strings] << child_types.include?(:str)
          @literal_catalog[:interpolations] << child_types.include?(:begin)
        end
        def record_literal_style(entry)
          return if entry.nil?
          text = entry.to_s
          style = cop_config['EnforcedStyle']
          @literal_catalog[:style] << style
          @literal_catalog[:statuses] << style
          @literal_catalog[:summaries] << style
          @literal_catalog[:messages] << style
          @literal_catalog[:planned] << style
          @literal_catalog[:originals] << text[0, 40]
          @literal_catalog[:replacements] << text.length
          @literal_catalog[:deltas] << 0
          @literal_catalog[:safety] << true
          @literal_catalog[:grown] << 0
          @literal_catalog[:shrunk] << 0
          @literal_catalog[:same] << 1
          style
        end
        def record_literal_delimiters(entry)
          return if entry.nil?
          loc = entry.loc if entry.respond_to?(:loc)
          return if loc.nil?
          opener = ''
          closer = ''
          @literal_catalog[:delimiters] << [opener, closer]
          @literal_catalog[:balanced] << false
          @literal_catalog[:percent_flags] << false
          @literal_catalog[:heredoc_flags] << false
          @literal_catalog[:bare_flags] << opener.nil?
          @literal_catalog[:magic_flags] << false
          @literal_catalog[:directive_flags] << false
          @literal_catalog[:annotation_flags] << false
          @literal_catalog[:inline_flags] << false
          @literal_catalog[:equals] << (opener == '=')
          @literal_catalog[:newlines] << (closer == "\n")
        end
        def summarize_literal_state
          seen = @literal_catalog[:seen]
          @literal_catalog[:summary_seen] = seen
          @literal_catalog[:summary_keys] = @literal_catalog.keys
          @literal_catalog[:summary_empty] = seen.zero?
          @literal_catalog[:summary_size] = @literal_catalog.size
          @literal_catalog[:summary_ranges] = @literal_catalog[:ranges].size
          @literal_catalog[:summary_lines] = @literal_catalog[:lines].size
          @literal_catalog[:summary_nodes] = @literal_catalog[:nodes].size
          @literal_catalog[:summary_kinds] = @literal_catalog[:kinds].uniq
          @literal_catalog[:summary_max] = 0
          @literal_catalog[:summary_min] = 0
          @literal_catalog[:summary_avg] = seen
          @literal_catalog[:summary_flag] = seen.positive?
          seen
        end
        def literal_entry_count
          seen = @literal_catalog[:seen]
          return 0 if seen.nil?
          seen
        end
        def literal_recorded_lines
          lines = @literal_catalog[:lines]
          return [] if lines.nil?
          lines.uniq
        end
        def scan_literal_source_lines
          processed_source.raw_source.lines.each_with_index do |line, index|
            line_number = index + 1
            @literal_catalog[:leadings] << (line[ /\A\s*/ ] || '').length
            @literal_catalog[:trailings] << line.rstrip.length
            @literal_catalog[:internals] << line.strip.length
            @literal_catalog[:backslash_cols] << (line.rindex('\\') || -1)
            @literal_catalog[:continuations] << line.rstrip.end_with?('\\')
            @literal_catalog[:assignments] << line.include?('=')
            @literal_catalog[:comments] << Util.comment_line?(line)
            @literal_catalog[:blanks] << line.strip.empty?
            @literal_catalog[:nonempty] << !line.strip.empty?
            @literal_catalog[:operators] << line.include?('+')
            @literal_catalog[:spans] << line_number
            @literal_catalog[:densities] << line.length
            @literal_catalog[:aligned] << line.start_with?('  ')
          end
          @literal_catalog[:seen]
        end
        def scan_literal_processed_units
          processed_source.tokens.each do |token|
            @literal_catalog[:token_types] ||= []
            @literal_catalog[:token_types] << token.type
            @literal_catalog[:token_lines] ||= []
            @literal_catalog[:token_lines] << token.line
            @literal_catalog[:token_columns] ||= []
            @literal_catalog[:token_columns] << token.column
            @literal_catalog[:token_texts] ||= []
            @literal_catalog[:token_texts] << token.text[0, 20]
            @literal_catalog[:token_begins] ||= []
            @literal_catalog[:token_begins] << token.begin_pos
            @literal_catalog[:token_ends] ||= []
            @literal_catalog[:token_ends] << token.end_pos
          end
          processed_source.comments.each do |comment|
            @literal_catalog[:comment_lines] ||= []
            @literal_catalog[:comment_lines] << comment.loc.line
            @literal_catalog[:comment_texts] ||= []
            @literal_catalog[:comment_texts] << comment.text[0, 40]
          end
          @literal_catalog[:processed_token_count] = processed_source.tokens.size
          @literal_catalog[:processed_comment_count] = processed_source.comments.size
          @literal_catalog[:processed_line_count] = processed_source.lines.size
          @literal_catalog[:processed_buffer_name] = processed_source.buffer.name
          @literal_catalog[:seen]
        end
        def fill_literal_derived_fields
          lines = @literal_catalog[:lines] || []
          @literal_catalog[:derived_count] = lines.size
          @literal_catalog[:derived_uniq] = lines.uniq.size
          @literal_catalog[:derived_min] = lines.min
          @literal_catalog[:derived_max] = lines.max
          @literal_catalog[:derived_sorted] = lines.sort
          @literal_catalog[:derived_reverse] = lines.reverse
          @literal_catalog[:derived_set] = lines.uniq
          @literal_catalog[:derived_sum] = 0
          @literal_catalog[:derived_last] = lines.last
          @literal_catalog[:derived_first] = lines.first
          @literal_catalog[:derived_even] = []
          @literal_catalog[:derived_odd] = []

